import React, { useState, useEffect } from 'react';

const ImageViewer = ({ content }) => {
  const [isOpen, setIsOpen] = useState(true);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);

  // If carousel is true, create an images array
  const images = content.carousel 
    ? [] // Add carousel image array if needed
    : [content.image];

  console.log('ImageViewer content:', content);
  console.log('Images:', images);

  const showSlide = (index) => {
    if (images.length === 0) return;

    if (index >= images.length) {
      setCurrentSlideIndex(0);
    } else if (index < 0) {
      setCurrentSlideIndex(images.length - 1);
    } else {
      setCurrentSlideIndex(index);
    }
  };

  const nextSlide = () => {
    showSlide(currentSlideIndex + 1);
  };

  const prevSlide = () => {
    showSlide(currentSlideIndex - 1);
  };

  const closeModal = () => {
    setIsOpen(false);
  };

  if (!isOpen || images.length === 0) return null;

  return (
    <div id="myModal" style={{display: 'block'}}>
      {content.carousel && images.length > 0 ? (
        <div className="carousel-container">
          <img 
            src={images[currentSlideIndex]} 
            alt={`Slide ${currentSlideIndex + 1}`} 
            style={{maxWidth: '100%', maxHeight: '80vh'}}
          />
          <button className="prev" onClick={prevSlide}>&#10094;</button>
          <button className="next" onClick={nextSlide}>&#10095;</button>
        </div>
      ) : (
        <img 
          id="modalImg" 
          src={images[0]} 
          alt="Selected" 
          style={{maxWidth: '100%', maxHeight: '80vh'}}
        />
      )}

      <div 
        id="caption" 
        dangerouslySetInnerHTML={{__html: content.text}}
      />
      <span className="close" onClick={closeModal}>&times;</span>
    </div>
  );
};

export default ImageViewer;
